from collections import deque


def sliding_window(iterable, n):
    window = deque(maxlen=n)
    for item in iterable:
        window.append(item)
        if len(window) == n:
            yield list(window)


def recent_items(stream, max_size):
    return deque(stream, maxlen=max_size)


def rotate_list(items, n):
    d = deque(items)
    d.rotate(n)
    return list(d)
